def upload(path: str) -> None:
    """Upload a file."""
    print(f"Uploading: {path}")

@app.command
def download(url: str, *, dest: str) -> None:
    """Download a file."""
    print(f"Downloading from {url} to {dest}")

if __name__ == "__main__":
